import json
import os

from app.appraisal_parser import parse

FIXTURES = os.path.join(os.path.dirname(__file__), 'fixtures')


def _lookup():
    with open(os.path.join(FIXTURES, 'lookup.json')) as f:
        return json.load(f)


def test_matches_php_output_for_mixed_paste():
    # Expected output generated by running the PHP regex chain from
    # src/routes.php over the same fixture (quantities as ints).
    with open(os.path.join(FIXTURES, 'paste.txt')) as f:
        result = parse(f.read(), _lookup())
    assert result == {34: 1235567, 35: 12445, 587: 3, 28668: 5, 40520: 2, 1: 3, 2488: 1}


def test_first_matching_pattern_wins_even_if_unknown():
    # "name<TAB>group<TAB>size<TAB>qty" matches the tab pattern with a greedy
    # name, so it is not found and later patterns are not tried.
    assert parse('200mm AutoCannon I\tProjectile Weapon\tSmall\t3', _lookup()) == {}


def test_blueprint_copies_skipped():
    assert parse('Rifter Blueprint Copy\t1', _lookup()) == {}


def test_empty_paste():
    assert parse('', _lookup()) == {}
